head.script:
scwin.onpageload = function () {
    dlt_a.setJSON([
        { "name" : "홍길동", "spnA" : "100", "spnB" : "100", "txt" : "100" },
        { "name" : "김철수", "spnA" : "200", "spnB" : "200", "txt" : "200" }
    ]);
};

// 결과 출력용 구분 ([A] spnA / [B] spnB / [C] txt)
scwin.getTag = function (colIndex) {
    let colId = grd_a.getColumnID(colIndex);
    if (colId === "spnA") {
        return "[A] ";
    }
    if (colId === "spnB") {
        return "[B] ";
    }
    if (colId === "txt") {
        return "[C] ";
    }
    return "";
};

// 편집 진입 직후 포커스 요소 출력
scwin.grd_a_onbeforeedit = function (rowIndex, colIndex, value) {
    let tag = scwin.getTag(colIndex);
    if (tag === "") {
        return;
    }
    let colId = grd_a.getColumnID(colIndex);
    setTimeout(function () {
        let el = document.activeElement;
        let isInput = el && el.tagName === "INPUT";
        scwin.setReturnValue(tag + dlt_a.getCellData(rowIndex, "name") + " 행 " + colId + " Cell 편집 진입 : 포커스 요소 " + (el ? el.tagName : "") + (isInput ? " (입력창 '" + el.value + "')" : " (입력창 포커스 없음)"));
    }, 100);
};

// 편집 종료 후 DataList 값 출력
scwin.grd_a_onafteredit = function (rowIndex, colIndex, value) {
    let tag = scwin.getTag(colIndex);
    if (tag === "") {
        return;
    }
    let colId = grd_a.getColumnID(colIndex);
    scwin.setReturnValue(tag + dlt_a.getCellData(rowIndex, "name") + " 행 " + colId + " Cell 편집 종료 : DataList 값 '" + dlt_a.getCellData(rowIndex, colId) + "'");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
